# ---------- 124. other players see your bullets fly too: a shot that leaves as a bullet is sent with where it started and
# how fast it is going, and is flown on their screens as a harmless streak that stops where it lands ----------
rep("  bullets.push({p,v,W,wpn:P.wpn,dist:nearT,t:0,l,off:muzzleV.clone().sub(p),tail:p.clone().add(muzzleV.clone().sub(p))});\n  return out; }",
    "  bullets.push({p,v,W,wpn:P.wpn,dist:nearT,t:0,l,off:muzzleV.clone().sub(p),tail:p.clone().add(muzzleV.clone().sub(p))});\n  out.ends=[]; out.b=[+p.x.toFixed(2),+p.y.toFixed(2),+p.z.toFixed(2),+v.x.toFixed(1),+v.y.toFixed(1),+v.z.toFixed(1)]; return out; }\n// someone else's bullet: seen, not felt (their own game decides what it hit)\nfunction ghostBullet(m,from){ const W=WEAPONS[m.w]; if(!W||!m.b||m.b.length!==6||bullets.length>80) return; const p=new THREE.Vector3(m.b[0],m.b[1],m.b[2]), v=new THREE.Vector3(m.b[3],m.b[4],m.b[5]); if(!isFinite(p.lengthSq()+v.lengthSq())||v.length()>600) return;\n  const g=new THREE.BufferGeometry().setFromPoints([from.clone(),from.clone()]), l=new THREE.Line(g,new THREE.LineBasicMaterial({color:0xffb070,transparent:true,opacity:0.95})); l.frustumCulled=false; scene.add(l);\n  bullets.push({p,v,W,wpn:m.w,dist:0,t:0,l,off:from.clone().sub(p),tail:from.clone(),ghost:true}); }")
rep("    const r=castShot(b.p,_bD,len,0,tgts); let tHit=r.kind==='none'?Infinity:r.t, what=r.kind;","    const r=castShot(b.p,_bD,len,0,b.ghost?[]:tgts); let tHit=r.kind==='none'?Infinity:r.t, what=r.kind;")
rep("      if(what==='body'){ const dd=dmg*(r.head?W.head:1); creditHit(r.who,{dmg:dd,head:r.head,pt},B?B.sh:0,b.wpn); }\n      else if(what==='piece') damagePiece(r.piece,dmg*(W.build||1),pt);",
    "      if(b.ghost){ if(what==='water') burst(pt,5,3.2,0.07,splashMat); else if(what==='ground') burst(pt,4,2.4,0.06,dustMat); }\n      else if(what==='body'){ const dd=dmg*(r.head?W.head:1); creditHit(r.who,{dmg:dd,head:r.head,pt},B?B.sh:0,b.wpn); }\n      else if(what==='piece') damagePiece(r.piece,dmg*(W.build||1),pt);")
